const items = $input.all();

return items.map(item => {
  const data = item.json.body || item.json;
  const errors = [];

  const requestId = data.request_id || "REQ-RISK-DEMO";
  const tenderId = data.tender_id || "TENDER-RISK-DEMO";
  const bidderId = data.bidder_id || "BIDDER-RISK-DEMO";
  const bidderName = (data.bidder_name || "ABC Technologies Pvt Ltd").toString().trim();

  let agentResults = data.agent_results;

  // Check if agent results array is provided
  if (agentResults !== undefined && agentResults !== null) {
    if (!Array.isArray(agentResults)) {
      errors.push("Field 'agent_results' must be an array");
      agentResults = [];
    }
  } else {
    agentResults = [];
  }

  const requiredAgents = Array.isArray(data.required_agents) ? data.required_agents : [];

  return {
    json: {
      request_id: requestId,
      tender_id: tenderId,
      bidder_id: bidderId,
      bidder_name: bidderName,
      agent_results: agentResults,
      required_agents: requiredAgents,
      valid_schema: errors.length === 0,
      validation_errors: errors,
      raw_input: data
    }
  };
});

const items = $input.all();

// Canonical list of known specialized agents in SIH-26100
const ALL_KNOWN_AGENTS = [
  "GST_AGENT",
  "PAN_AGENT",
  "UDYAM_AGENT",
  "FINANCIAL_AGENT",
  "DOCUMENT_FORENSICS_AGENT",
  "EXPERIENCE_AGENT",
  "ENTITY_RESOLUTION_AGENT"
];

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const receivedResults = data.agent_results || [];
  const resultMap = new Map();

  receivedResults.forEach(r => {
    if (r && r.agent) {
      resultMap.set(r.agent.toUpperCase(), r);
    }
  });

  const evaluatedAgents = [];
  const missingRequired = [];

  // Identify which agents were required vs received (only when agent_results are provided for cross-evaluation)
  const required = (receivedResults.length > 0 && data.required_agents && data.required_agents.length > 0) 
    ? data.required_agents.map(a => a.toUpperCase())
    : [];

  required.forEach(req => {
    if (req !== 'RISK_INTELLIGENCE_AGENT' && req !== 'FINAL_COMPLIANCE_AGENT' && !resultMap.has(req)) {
      missingRequired.push(req);
    }
  });

  receivedResults.forEach(r => {
    evaluatedAgents.push({
      agent: (r.agent || 'UNKNOWN_AGENT').toUpperCase(),
      status: (r.status || 'UNKNOWN').toUpperCase(),
      confidence: typeof r.confidence === 'number' ? r.confidence : 1.0,
      risk_level: (r.risk_level || 'LOW').toUpperCase(),
      issues: Array.isArray(r.issues) ? r.issues : (r.issues ? [String(r.issues)] : [])
    });
  });

  // Add explicit NOT_EXECUTED entries for missing required agents
  missingRequired.forEach(missingAgent => {
    evaluatedAgents.push({
      agent: missingAgent,
      status: 'NOT_EXECUTED',
      confidence: 0.0,
      risk_level: 'HIGH',
      issues: [`Required agent ${missingAgent} was not executed or returned no result`]
    });
  });

  return {
    json: {
      ...data,
      collected_agents: evaluatedAgents,
      missing_required_agents: missingRequired
    }
  };
});

const items = $input.all();

function mapAgentToCategory(agent) {
  const a = agent.toUpperCase();
  if (a.includes('GST') || a.includes('PAN') || a.includes('UDYAM')) return 'STATUTORY_RISK';
  if (a.includes('FINANC')) return 'FINANCIAL_RISK';
  if (a.includes('FORENSIC') || a.includes('DOC')) return 'DOCUMENT_RISK';
  if (a.includes('EXPERIENCE') || a.includes('ELIGIBIL')) return 'EXPERIENCE_RISK';
  if (a.includes('ENTITY') || a.includes('RESOLUT')) return 'IDENTITY_RISK';
  return 'GENERAL_RISK';
}

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const agents = data.collected_agents || [];
  const signals = [];
  const failedAgents = [];
  const errorAgents = [];
  const notExecutedAgents = [];

  agents.forEach(a => {
    const category = mapAgentToCategory(a.agent);

    if (a.status === 'NOT_VERIFIED') {
      failedAgents.push(a.agent);
      signals.push({
        agent: a.agent,
        type: 'STATUS_FAILURE',
        category,
        severity: 'HIGH',
        penalty: 40,
        description: `${a.agent} failed compliance verification (NOT_VERIFIED)`,
        issues: a.issues
      });
    } else if (a.status === 'ERROR') {
      errorAgents.push(a.agent);
      signals.push({
        agent: a.agent,
        type: 'SYSTEM_ERROR',
        category: 'SYSTEM_ERROR_RISK',
        severity: 'HIGH',
        penalty: 40,
        description: `${a.agent} encountered an execution error (ERROR)`,
        issues: a.issues
      });
    } else if (a.status === 'NOT_EXECUTED') {
      notExecutedAgents.push(a.agent);
      signals.push({
        agent: a.agent,
        type: 'UNEXECUTED_AGENT',
        category: 'EXECUTION_RISK',
        severity: 'HIGH',
        penalty: 40,
        description: `Required agent ${a.agent} did not execute`,
        issues: a.issues
      });
    } else if (a.status === 'VERIFIED') {
      // Check secondary risk levels on verified agents (non-critical anomalies)
      if (a.risk_level === 'HIGH') {
        signals.push({
          agent: a.agent,
          type: 'ANOMALY_HIGH',
          category,
          severity: 'HIGH',
          penalty: 30,
          description: `${a.agent} passed but flagged high residual risk`,
          issues: a.issues
        });
      } else if (a.risk_level === 'MEDIUM') {
        signals.push({
          agent: a.agent,
          type: 'ANOMALY_MEDIUM',
          category,
          severity: 'MEDIUM',
          penalty: 15,
          description: `${a.agent} passed with minor anomalies / review indicators`,
          issues: a.issues
        });
      }
    }
  });

  return {
    json: {
      ...data,
      extracted_signals: signals,
      failed_agents: failedAgents,
      error_agents: errorAgents,
      not_executed_agents: notExecutedAgents
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const agents = data.collected_agents || [];
  const confidenceFlags = [];
  const confidenceSignals = [];

  agents.forEach(a => {
    // Only inspect confidence if agent actually executed
    if (a.status !== 'NOT_EXECUTED') {
      if (a.confidence < 0.70) {
        confidenceFlags.push(`${a.agent} has low confidence (${a.confidence})`);
        confidenceSignals.push({
          agent: a.agent,
          type: 'CONFIDENCE_LOW',
          category: 'CONFIDENCE_RISK',
          severity: 'HIGH',
          penalty: 20,
          description: `${a.agent} returned low evaluation confidence (${a.confidence} < 0.70)`
        });
      } else if (a.confidence < 0.90) {
        confidenceFlags.push(`${a.agent} has moderate confidence (${a.confidence})`);
        confidenceSignals.push({
          agent: a.agent,
          type: 'CONFIDENCE_MEDIUM',
          category: 'CONFIDENCE_RISK',
          severity: 'MEDIUM',
          penalty: 10,
          description: `${a.agent} returned moderate evaluation confidence (${a.confidence} in [0.70, 0.90))`
        });
      }
    }
  });

  return {
    json: {
      ...data,
      confidence_flags: confidenceFlags,
      confidence_signals: confidenceSignals
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const extracted = data.extracted_signals || [];
  const confSignals = data.confidence_signals || [];
  const allSignals = [...extracted, ...confSignals];

  // Cumulative calculation with 100-point ceiling cap
  let totalScore = 0;
  const distinctCategories = new Set();

  allSignals.forEach(sig => {
    totalScore += (sig.penalty || 0);
    if (sig.category) distinctCategories.add(sig.category);
  });

  const cappedScore = Math.min(100, Math.max(0, totalScore));

  let riskLevel = 'LOW';
  if (cappedScore >= 50) {
    riskLevel = 'HIGH';
  } else if (cappedScore >= 20) {
    riskLevel = 'MEDIUM';
  } else {
    riskLevel = 'LOW';
  }

  return {
    json: {
      ...data,
      all_signals: allSignals,
      calculated_risk_score: cappedScore,
      calculated_risk_level: riskLevel,
      risk_categories: Array.from(distinctCategories)
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;

  let status = "VERIFIED";
  let confidence = 0.98;
  let riskLevel = "LOW";
  let riskScore = 0;
  const allIssues = [];

  if (!data.valid_schema) {
    status = "ERROR";
    confidence = 0.0;
    riskLevel = "HIGH";
    riskScore = 100;
    allIssues.push(...(data.validation_errors || ["Invalid risk input data structure"]));
  } else {
    riskScore = data.calculated_risk_score || 0;
    riskLevel = data.calculated_risk_level || 'LOW';

    // Populate issues from all signals
    const signals = data.all_signals || [];
    signals.forEach(s => {
      allIssues.push(s.description);
    });

    // Status determination for Risk Intelligence Agent:
    // Passes as VERIFIED analysis engine
    status = "VERIFIED";
    confidence = 0.98;
  }

  const agents = data.collected_agents || [];

  return {
    json: {
      agent: "RISK_INTELLIGENCE_AGENT",
      status,
      confidence,
      evidence: {
        agents_evaluated: agents.length,
        risk_score: riskScore,
        risk_level: riskLevel,
        risk_categories: data.risk_categories || [],
        risk_signals: data.all_signals || [],
        failed_agents: data.failed_agents || [],
        error_agents: data.error_agents || [],
        not_executed_agents: data.not_executed_agents || [],
        confidence_flags: data.confidence_flags || [],
        scoring_version: "RISK_RULES_V1",
        registry_source: "ORCHESTRATOR_AGENT_RESULTS"
      },
      issues: allIssues,
      risk_level: riskLevel,
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();
return items.map(item => ({
  json: item.json
}));

const items = $input.all();
return items.map(item => ({
  json: {
    agent: "RISK_INTELLIGENCE_AGENT",
    status: "ERROR",
    confidence: 0.0,
    evidence: {
      error: "Risk intelligence agent encountered an unexpected execution failure",
      fallback_mode: true
    },
    issues: ["Risk intelligence agent failed unexpectedly"],
    risk_level: "HIGH",
    timestamp: new Date().toISOString()
  }
}));
